/* ios_gnutls_shim.h — redirect dlopen/dlsym/dlclose to a static symbol
 * table for Wine's GnuTLS-backed unixlibs (bcrypt, secur32/schannel,
 * crypt32).
 *
 * Those files runtime-load libgnutls via dlopen(SONAME_LIBGNUTLS) +
 * dlsym per function. On iOS there is no gnutls dylib — we link
 * toolchains/gnutls-ios/lib/libgnutls.a statically into Madeira.app and
 * resolve through the table generated by gen_gnutls_symtab.sh (which
 * also serves as the linker anchor so dead-stripping can't drop the
 * gnutls objects these files need).
 *
 * Injected with -include BEFORE the source: when <dlfcn.h> is included
 * later, its declarations expand through these function-like macros
 * into declarations of our shims (same signatures), which is exactly
 * what we want. dlerror() stays real.
 *
 * Non-gnutls dlopen names fall through to the real dlopen inside
 * ios_gnutls_dlopen, so this header is safe even if a future version
 * of these files loads something else too. */
#pragma once

/* The host configure cannot link the iOS archive when probing GnuTLS.
 * These unixlibs use the pinned static iOS build through the symbol table. */
#ifndef HAVE_GNUTLS_CIPHER_INIT
#define HAVE_GNUTLS_CIPHER_INIT 1
#endif
#ifndef SONAME_LIBGNUTLS
#define SONAME_LIBGNUTLS "libgnutls.dylib"
#endif

extern void *ios_gnutls_dlopen(const char *name, int flags);
extern void *ios_gnutls_dlsym(void *handle, const char *name);
extern int   ios_gnutls_dlclose(void *handle);

#define dlopen(name, flags)  ios_gnutls_dlopen(name, flags)
#define dlsym(handle, name)  ios_gnutls_dlsym(handle, name)
#define dlclose(handle)      ios_gnutls_dlclose(handle)
